import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.temporal.TemporalAdjusters;

public class TimeDemonstration {
    public static void main(String[] args) {
        // Immutable date creation
        LocalDate today = LocalDate.now();

        // Using TemporalAdjusters for business logic
        LocalDate lastDayOfMonth = today.with(TemporalAdjusters.lastDayOfMonth());

        // Timezone awareness
        ZonedDateTime localizedTime = ZonedDateTime.now(ZoneId.of("America/New_York"));

        System.out.println("Today: " + today);
        System.out.println("Last day of month: " + lastDayOfMonth);
        System.out.println("New York Time: " + localizedTime);
    }
}
